<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= escapar_html($tituloPagina) ?></title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><main class="container py-5"><div class="col-md-7 mx-auto"><a href="/produtos">← Voltar aos produtos</a><section class="card border-0 shadow-sm mt-3"><div class="card-body p-4"><h1 class="h3">Cadastrar produto</h1><?php if($erros):?><div class="alert alert-danger"><ul class="mb-0"><?php foreach($erros as $erro):?><li><?= escapar_html($erro) ?></li><?php endforeach;?></ul></div><?php endif;?><form method="post"><input type="hidden" name="token_csrf" value="<?= escapar_html($tokenCsrf) ?>"><div class="mb-3"><label class="form-label">Nome</label><input class="form-control" name="nome" maxlength="150" required value="<?= escapar_html($dadosProduto['nome']) ?>"></div><div class="mb-3"><label class="form-label">Descrição</label><textarea class="form-control" name="descricao"><?= escapar_html($dadosProduto['descricao']) ?></textarea></div><div class="mb-3"><label class="form-label">Preço</label><input class="form-control" name="preco" inputmode="decimal" required value="<?= escapar_html($dadosProduto['preco']===false?'':$dadosProduto['preco']) ?>"></div><button class="btn btn-primary">Cadastrar</button></form></div></section></div></main></body></html>
